// Valida e processa dados IoT no novo formato
const webhookData = $input.first().json;
const iotData = webhookData.body;

// Validação básica dos dados
const requiredFields = ['id', 'CO2', 'PM1_0', 'PM2_5', 'PM4_0', 'PM_10', 'TypPS', 'T', 'H', 'P', 'G', 'sIAQ'];
const missingFields = requiredFields.filter(field => !iotData[field]);

if (missingFields.length > 0) {
  throw new Error(`Campos obrigatórios ausentes: ${missingFields.join(', ')}`);
}

// Valida valores numéricos
const numericFields = ['CO2', 'PM1_0', 'PM2_5', 'PM4_0', 'PM_10', 'TypPS', 'T', 'H', 'P', 'G', 'sIAQ'];
const invalidFields = numericFields.filter(field => {
  const value = iotData[field];
  return value !== undefined && (isNaN(parseFloat(value)) || parseFloat(value) < 0);
});

if (invalidFields.length > 0) {
  throw new Error(`Valores inválidos para campos: ${invalidFields.join(', ')}`);
}

// Processa e normaliza os dados
const processedData = {
  sensor_id: iotData.id,
  timestamp: $now,
  pollutants: {
    co2: parseFloat(iotData.CO2) || null,
    pm25: parseFloat(iotData.PM2_5) || null,
    pm10: parseFloat(iotData.PM_10) || null,
    pm1: parseFloat(iotData.PM1_0) || null,
    pm4: parseFloat(iotData.PM4_0) || null,
    co: parseFloat(iotData.TypPS) || null,
    gas: parseFloat(iotData.G) || null
  },
  environmental: {
    temperature: parseFloat(iotData.T) || null,
    humidity: parseFloat(iotData.H) || null,
    pressure: parseFloat(iotData.P) || null
  },
  air_quality_index: parseFloat(iotData.sIAQ) || null,
  validation_status: 'valid',
  processed_at: new Date().toISOString()
};

return {
  json: processedData
};

// Processa a análise da IA e gera alertas
const aiResponse = $input.first().json.output;
let analysis;

try {
  // Tenta extrair JSON da resposta da IA
  const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  }
} catch (error) {
  console.error('Erro ao processar resposta da IA:', error);
  analysis = {
    risk_level: 'unknown',
    affected_diseases: []
  };
}
const alert = {analysis};

return {
  json: alert
}

